const dispatchKey='arrest-dispatch-at';
const duration=30*60*1000;
const startedAt=fields=>Number.isFinite(fields[dispatchKey])&&fields[dispatchKey]>0?fields[dispatchKey]:null;
export function dispatchSeconds(fields,now=Date.now()){const at=startedAt(fields);return at===null?duration/1000:Math.max(0,Math.min(duration/1000,Math.ceil((at+duration-now)/1000)));}
const timerText=seconds=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
const status=fields=>startedAt(fields)===null?'Confirm pulselessness, call dispatch for a 30-minute timer, then tap.':dispatchSeconds(fields)===0?'30 minutes reached':'Dispatch timer running';
const clock=at=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(at));
export function dispatchTimerPanel(fields,icon){const at=startedAt(fields);return `<section class="dispatch-timer ${at!==null&&dispatchSeconds(fields)===0?'reached':''}" aria-labelledby="dispatch-title"><div class="dispatch-heading"><h2 id="dispatch-title">${icon('clock')} Dispatch · 30-minute timer</h2><span class="dispatch-digits" role="timer" aria-label="Dispatch timer remaining">${timerText(dispatchSeconds(fields))}</span></div><button class="dispatch-start" data-dispatch-timer="start" ${at!==null?'disabled':''}>${icon(at===null?'clock':'check')}<span>${at===null?'Called dispatch · Start 30 min':'Dispatch call recorded'}</span></button><p class="dispatch-status" role="status" aria-live="polite">${status(fields)}</p>${at!==null?`<div class="dispatch-record"><time datetime="${new Date(at).toISOString()}">Called · ${clock(at)}</time><button data-dispatch-timer="clear">Clear time</button></div>`:''}</section>`;}
export function refreshDispatchTimer(fields){const panel=document.querySelector('.dispatch-timer');if(!panel)return;panel.querySelector('.dispatch-digits').textContent=timerText(dispatchSeconds(fields));const text=status(fields),label=panel.querySelector('.dispatch-status');if(label.textContent!==text)label.textContent=text;panel.classList.toggle('reached',startedAt(fields)!==null&&dispatchSeconds(fields)===0);}
export function bindArrestTools(getState,save,render){document.addEventListener('click',e=>{const button=e.target.closest('[data-dispatch-timer]');if(!button)return;const fields=getState().fields;if(button.dataset.dispatchTimer==='start'){if(startedAt(fields)!==null)return;fields[dispatchKey]=Date.now();}else if(button.dataset.dispatchTimer==='clear'){delete fields[dispatchKey];}else return;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-dispatch-timer="${button.dataset.dispatchTimer==='start'?'clear':'start'}"]`)?.focus({preventScroll:true});});}
